<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>롯데월드타워: 설계와 형상의 탄생</title>
    <style>
        :root {
            --bg-color: #0b0c10;
            --panel-bg: rgba(31, 40, 51, 0.85);
            --text-color: #c5c6c7;
            --accent-color: #66fcf1;
            --secondary-color: #45a29e;
            --font-family: 'Noto Sans KR', sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
            user-select: none;
        }

        body {
            font-family: var(--font-family);
            background-color: var(--bg-color);
            color: var(--text-color);
            overflow: hidden;
            width: 100vw;
            height: 100vh;
        }

        /* 3D Canvas */
        #canvas-container {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 1;
        }

        /* UI Overlay */
        #ui-layer {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 2;
            pointer-events: none; /* Let clicks pass through to 3D */
            display: flex;
            flex-direction: column;
            justify-content: space-between;
        }

        /* Header */
        header {
            padding: 20px;
            background: linear-gradient(to bottom, rgba(0,0,0,0.8), transparent);
            pointer-events: auto;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        h1 {
            font-size: 1.5rem;
            color: var(--accent-color);
            text-shadow: 0 0 10px rgba(102, 252, 241, 0.3);
        }

        .model-badge {
            font-size: 0.8rem;
            background: rgba(102, 252, 241, 0.1);
            border: 1px solid var(--accent-color);
            padding: 4px 8px;
            border-radius: 4px;
        }

        /* Main Content Area */
        main {
            flex: 1;
            display: flex;
            position: relative;
        }

        /* Left Panel: Controls & Info */
        #control-panel {
            width: 320px;
            background: var(--panel-bg);
            backdrop-filter: blur(10px);
            border-right: 1px solid rgba(255,255,255,0.1);
            padding: 20px;
            pointer-events: auto;
            overflow-y: auto;
            display: flex;
            flex-direction: column;
            gap: 20px;
            transition: transform 0.3s ease;
        }

        .panel-section {
            border-bottom: 1px solid rgba(255,255,255,0.1);
            padding-bottom: 15px;
        }

        .panel-section:last-child {
            border-bottom: none;
        }

        h2 {
            font-size: 1rem;
            color: var(--secondary-color);
            margin-bottom: 10px;
            text-transform: uppercase;
            letter-spacing: 1px;
        }

        /* Tabs */
        .tabs {
            display: flex;
            gap: 5px;
            margin-bottom: 10px;
        }

        .tab-btn {
            flex: 1;
            background: rgba(255,255,255,0.05);
            border: 1px solid transparent;
            color: var(--text-color);
            padding: 8px;
            cursor: pointer;
            font-size: 0.85rem;
            transition: all 0.2s;
        }

        .tab-btn.active {
            background: var(--secondary-color);
            color: #fff;
            font-weight: bold;
        }

        .tab-btn:hover:not(.active) {
            background: rgba(255,255,255,0.1);
        }

        /* Content Display */
        .content-display {
            min-height: 150px;
            font-size: 0.9rem;
            line-height: 1.5;
        }

        .content-display p {
            margin-bottom: 10px;
        }

        .dimension-box {
            background: rgba(0,0,0,0.3);
            padding: 10px;
            border-radius: 4px;
            font-family: monospace;
            font-size: 0.8rem;
            color: var(--accent-color);
            margin-top: 5px;
        }

        /* 3D Viewport Overlay (Top Right) */
        #viewport-overlay {
            position: absolute;
            top: 20px;
            right: 20px;
            width: 200px;
            background: var(--panel-bg);
            backdrop-filter: blur(5px);
            padding: 15px;
            border-radius: 8px;
            pointer-events: auto;
            border: 1px solid rgba(255,255,255,0.1);
        }

        .view-controls {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .view-btn {
            background: transparent;
            border: 1px solid var(--secondary-color);
            color: var(--secondary-color);
            padding: 8px;
            cursor: pointer;
            border-radius: 4px;
            font-size: 0.8rem;
            transition: 0.2s;
        }

        .view-btn:hover {
            background: var(--secondary-color);
            color: #fff;
        }

        /* Footer */
        footer {
            padding: 10px 20px;
            background: linear-gradient(to top, rgba(0,0,0,0.8), transparent);
            font-size: 0.75rem;
            color: rgba(255,255,255,0.5);
            pointer-events: auto;
            text-align: center;
        }

        /* Loading */
        #loader {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: var(--bg-color);
            z-index: 100;
            display: flex;
            justify-content: center;
            align-items: center;
            flex-direction: column;
            transition: opacity 0.5s;
        }

        .spinner {
            width: 40px;
            height: 40px;
            border: 4px solid var(--secondary-color);
            border-top: 4px solid var(--accent-color);
            border-radius: 50%;
            animation: spin 1s linear infinite;
            margin-bottom: 15px;
        }

        @keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }

        /* Responsive */
        @media (max-width: 768px) {
            #control-panel {
                position: absolute;
                bottom: 0;
                left: 0;
                width: 100%;
                height: 40%;
                border-right: none;
                border-top: 1px solid rgba(255,255,255,0.1);
                transform: translateY(0);
            }
            #viewport-overlay {
                top: 10px;
                right: 10px;
                width: 160px;
                padding: 10px;
            }
            h1 { font-size: 1.2rem; }
        }
    </style>
</head>
<body>

    <!-- Loading Screen -->
    <div id="loader">
        <div class="spinner"></div>
        <div>설계 데이터 로딩 중...</div>
    </div>

    <!-- 3D Scene Container -->
    <div id="canvas-container"></div>

    <!-- UI Layer -->
    <div id="ui-layer">
        <header>
            <h1>롯데월드타워 <span style="font-size:0.8em; opacity:0.7;">| 설계와 형상의 탄생</span></h1>
            <div class="model-badge">glm-4.7-flash</div>
        </header>

        <main>
            <!-- Left Control Panel -->
            <aside id="control-panel">
                <div class="panel-section">
                    <h2>설계 단계 선택</h2>
                    <div class="tabs">
                        <button class="tab-btn active" onclick="app.setStage('layout')">배치도</button>
                        <button class="tab-btn" onclick="app.setStage('plan')">기준층 평면</button>
                        <button class="tab-btn" onclick="app.setStage('elevation')">입면도</button>
                        <button class="tab-btn" onclick="app.setStage('section')">단면도</button>
                    </div>
                    <div id="stage-info" class="content-display">
                        <p>서울 송파구에 위치한 롯데월드타워는 555m의 높이를 자랑하는 세계 5대 빌딩 중 하나입니다. 이 프로젝트는 형태의 유연함과 구조적 안정성을 동시에 고려한 복합적인 설계 과정을 거쳤습니다.</p>
                    </div>
                </div>

                <div class="panel-section">
                    <h2>도면 정보</h2>
                    <div id="drawing-info" class="content-display">
                        <p>배치도는 건물이 주변 환경과 어떻게 조화를 이루는지 보여줍니다.</p>
                        <div class="dimension-box">단위: 미터 (m)</div>
                    </div>
                </div>

                <div class="panel-section">
                    <h2>설계 컨셉</h2>
                    <div id="concept-info" class="content-display">
                        <p><strong>형상:</strong> 위로 갈수록 면적이 좁아지는 형태로, 지진에 대한 저항성을 높이고 공기 저항을 줄입니다.</p>
                        <p><strong>스타일:</strong> KPF는 한국 도자기의 선을 참고하여, 건물의 외관에 유려한 곡선을 적용했습니다.</p>
                    </div>
                </div>
            </aside>

            <!-- Top Right Viewport Controls -->
            <div id="viewport-overlay">
                <h2>조작</h2>
                <div class="view-controls">
                    <button class="view-btn" onclick="app.resetCamera()">시점 초기화</button>
                    <button class="view-btn" onclick="app.toggleAutoRotate()">자동 회전: <span id="rotate-status">OFF</span></button>
                    <button class="view-btn" onclick="app.toggleWireframe()">와이어프레임 모드</button>
                </div>
            </div>
        </main>

        <footer>
            자료 출처: KPF, LERA (개념 재구성) | WebGL Rendering
        </footer>
    </div>

    <!-- Import Map for Three.js (No external network needed if using local, but using CDN for standard Three.js) -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.186.1/build/three.module.js",
                "three/addons/": "https://unpkg.com/three@0.186.1/examples/jsm/"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';
        import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

        // --- Data & Configuration ---
        const CONFIG = {
            height: 555,
            floors: 123,
            baseRadius: 40, // Conceptual radius at base
            topRadius: 8,   // Conceptual radius at top
            taperFactor: 0.85, // How much it tapers
            color: 0x66fcf1,
            glassColor: 0x88ccff,
            structureColor: 0x333333
        };

        const STAGE_DATA = {
            layout: {
                title: "배치도",
                desc: "롯데월드타워는 송파구의 지형을 고려하여 배치되었습니다. 주변에 있는 롯데월드 아쿠아리움과의 조화를 위해 건물의 중심을 약간 오프셋하여 배치했습니다. 이는 시각적 균형을 맞추고 주변 경관을 최대한 활용하기 위함입니다.",
                drawing: "건물의 전체적인 위치와 주변 환경(롯데월드, 한강)의 관계를 보여줍니다. 건물은 서울의 중심부에 위치하며, 주요 도로망과의 연결성을 고려하여 배치되었습니다.",
                cameraPos: { x: 200, y: 150, z: 200 },
                target: { x: 0, y: 100, z: 0 }
            },
            plan: {
                title: "기준층 평면도",
                desc: "기준층(1층)의 평면도입니다. 건물의 형태는 위로 갈수록 좁아지는 '타원형'을 띱니다. 이는 지진에 대한 구조적 안정성을 높이고, 공기 저항을 줄여 고층 빌딩의 효율성을 높이는 설계 철학입니다.",
                drawing: "1층의 전체적인 평면 형상입니다. 중앙에 있는 공원과 연결되는 입구가 있으며, 주요 업무 공간이 중앙에 집중되어 있습니다.",
                cameraPos: { x: 0, y: 10, z: 100 },
                target: { x: 0, y: 0, z: 0 }
            },
            elevation: {
                title: "입면도",
                desc: "건물의 외관은 한국 도자기의 선을 참고하여 설계되었습니다. 유려한 곡선이 적용되어, 단순한 기둥이 아닌 유기적인 형태를 띱니다. 이는 건물이 바람에 흔들리는 것을 줄이고, 시각적으로도 부드러운 느낌을 줍니다.",
                drawing: "건물의 전면(동쪽)을 바라본 입면도입니다. 도자기의 곡선이 반영된 외벽이 드러납니다.",
                cameraPos: { x: 100, y: 50, z: 0 },
                target: { x: 0, y: 100, z: 0 }
            },
            section: {
                title: "단면도",
                desc: "건물의 단면도는 위로 갈수록 면적이 줄어드는 형태를 보여줍니다. 이는 구조적 효율성을 높이는 '타워 형태'의 핵심입니다. 또한, 각 층마다 창호의 크기와 위치가 변화하여 건물의 입체적인 느낌을 부여합니다.",
                drawing: "건물의 횡단면입니다. 기둥의 배치와 외벽의 곡선이 단면에서도 명확히 드러납니다.",
                cameraPos: { x: 0, y: 50, z: 100 },
                target: { x: 0, y: 100, z: 0 }
            }
        };

        // --- Application Class ---
        class App {
            constructor() {
                this.container = document.getElementById('canvas-container');
                this.scene = null;
                this.camera = null;
                this.renderer = null;
                this.controls = null;
                this.modelGroup = new THREE.Group();
                this.wireframeGroup = new THREE.Group();
                this.currentStage = 'layout';
                this.isAutoRotating = false;
                this.isWireframe = false;

                this.init();
                this.createScene();
                this.animate();
                this.setupEvents();

                // Remove loader
                setTimeout(() => {
                    document.getElementById('loader').style.opacity = '0';
                    setTimeout(() => document.getElementById('loader').remove(), 500);
                }, 1000);
            }

            init() {
                // Scene
                this.scene = new THREE.Scene();
                this.scene.background = new THREE.Color(0x0b0c10);
                this.scene.fog = new THREE.FogExp2(0x0b0c10, 0.0015);

                // Camera
                this.camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 1, 2000);
                this.camera.position.set(200, 150, 200);

                // Renderer
                this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
                this.renderer.setSize(window.innerWidth, window.innerHeight);
                this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
                this.renderer.shadowMap.enabled = true;
                this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
                this.container.appendChild(this.renderer.domElement);

                // Controls
                this.controls = new OrbitControls(this.camera, this.renderer.domElement);
                this.controls.enableDamping = true;
                this.controls.dampingFactor = 0.05;
                this.controls.maxPolarAngle = Math.PI / 2 - 0.05; // Prevent going under ground
                this.controls.minDistance = 50;
                this.controls.maxDistance = 600;

                // Lights
                const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
                this.scene.add(ambientLight);

                const dirLight = new THREE.DirectionalLight(0xffffff, 1);
                dirLight.position.set(100, 200, 100);
                dirLight.castShadow = true;
                dirLight.shadow.mapSize.width = 2048;
                dirLight.shadow.mapSize.height = 2048;
                this.scene.add(dirLight);

                const backLight = new THREE.DirectionalLight(0x66fcf1, 0.5);
                backLight.position.set(-100, 100, -100);
                this.scene.add(backLight);

                // Ground
                const groundGeo = new THREE.PlaneGeometry(2000, 2000);
                const groundMat = new THREE.MeshStandardMaterial({ 
                    color: 0x1f2833, 
                    roughness: 0.8,
                    metalness: 0.2
                });
                const ground = new THREE.Mesh(groundGeo, groundMat);
                ground.rotation.x = -Math.PI / 2;
                ground.receiveShadow = true;
                this.scene.add(ground);

                // Grid Helper
                const gridHelper = new THREE.GridHelper(1000, 50, 0x45a29e, 0x1f2833);
                this.scene.add(gridHelper);

                // Add Groups
                this.scene.add(this.modelGroup);
                this.scene.add(this.wireframeGroup);
                this.wireframeGroup.visible = false;
            }

            createScene() {
                // 1. Create the Tower Geometry (Procedural)
                // Using a custom shape to simulate the tapering and curves
                const heightSegments = 60;
                const radiusSegments = 40;
                const geometry = new THREE.CylinderGeometry(
                    CONFIG.baseRadius, 
                    CONFIG.topRadius, 
                    CONFIG.height, 
                    radiusSegments, 
                    heightSegments, 
                    true // Open ended
                );

                // Apply tapering and curve logic manually to vertices for "Korean Pottery" look
                const posAttribute = geometry.attributes.position;
                const vertex = new THREE.Vector3();

                for (let i = 0; i < posAttribute.count; i++) {
                    vertex.fromBufferAttribute(posAttribute, i);

                    // Y is height
                    const y = vertex.y;
                    const normalizedY = y / CONFIG.height; // 0 to 1

                    // Calculate radius at this height (Linear taper)
                    const currentRadius = CONFIG.baseRadius - (normalizedY * (CONFIG.baseRadius - CONFIG.topRadius));

                    // Apply "Pottery Curve" (Sine wave distortion based on height)
                    // This makes the tower look organic, not just a cone
                    const curveIntensity = 0.15; 
                    const curve = Math.sin(normalizedY * Math.PI * 2) * curveIntensity * currentRadius;

                    // Apply curve to X and Z
                    vertex.x = vertex.x / currentRadius * (currentRadius + curve);
                    vertex.z = vertex.z / currentRadius * (currentRadius + curve);

                    posAttribute.setXYZ(i, vertex.x, vertex.y, vertex.z);
                }

                geometry.computeVertexNormals();

                // 2. Create Materials
                // Glass Material
                const glassMaterial = new THREE.MeshPhysicalMaterial({
                    color: CONFIG.glassColor,
                    metalness: 0.1,
                    roughness: 0.1,
                    transmission: 0.6, // Glass-like
                    thickness: 1.0,
                    transparent: true,
                    opacity: 0.8,
                    side: THREE.DoubleSide
                });

                // Structure Material (The "Frame")
                const structureMaterial = new THREE.MeshStandardMaterial({
                    color: CONFIG.structureColor,
                    roughness: 0.5,
                    metalness: 0.8
                });

                // 3. Create Meshes
                // Main Glass Body
                const towerMesh = new THREE.Mesh(geometry, glassMaterial);
                towerMesh.castShadow = true;
                towerMesh.receiveShadow = true;
                this.modelGroup.add(towerMesh);

                // Wireframe Overlay (for the "Design" look)
                const wireframeGeo = new THREE.WireframeGeometry(geometry);
                const wireframeMat = new THREE.LineBasicMaterial({ color: 0x66fcf1, transparent: true, opacity: 0.15 });
                const wireframe = new THREE.LineSegments(wireframeGeo, wireframeMat);
                this.wireframeGroup.add(wireframe);

                // 4. Add "Design Stages" Visuals (Helper Lines)
                // Base Platform
                const baseGeo = new THREE.CylinderGeometry(CONFIG.baseRadius * 1.1, CONFIG.baseRadius * 1.1, 2, 64);
                const baseMesh = new THREE.Mesh(baseGeo, structureMaterial);
                baseMesh.position.y = -1;
                this.modelGroup.add(baseMesh);

                // Top Cap
                const topGeo = new THREE.CylinderGeometry(CONFIG.topRadius * 1.2, CONFIG.topRadius * 1.2, 5, 32);
                const topMesh = new THREE.Mesh(topGeo, structureMaterial);
                topMesh.position.y = CONFIG.height / 2;
                this.modelGroup.add(topMesh);

                // 5. Add "Reference Lines" for Stages
                // These are helper lines that appear when switching stages
                this.createStageHelpers();
            }

            createStageHelpers() {
                // Helper Group
                this.helpers = new THREE.Group();
                this.modelGroup.add(this.helpers);

                // 1. Layout Helper: Ground Plane Outline
                const layoutHelper = new THREE.Group();
                const layoutRing = new THREE.Mesh(
                    new THREE.RingGeometry(CONFIG.baseRadius * 1.2, CONFIG.baseRadius * 1.2, 64),
                    new THREE.MeshBasicMaterial({ color: 0x66fcf1, side: THREE.DoubleSide, transparent: true, opacity: 0.3 })
                );
                layoutRing.rotation.x = -Math.PI / 2;
                layoutRing.position.y = 0.1;
                layoutHelper.add(layoutRing);
                layoutHelper.userData = { name: 'layout' };
                this.helpers.add(layoutHelper);

                // 2. Plan Helper: Base Floor Outline
                const planHelper = new THREE.Group();
                const planRing = new THREE.Mesh(
                    new THREE.RingGeometry(CONFIG.baseRadius * 0.9, CONFIG.baseRadius * 0.9, 64),
                    new THREE.MeshBasicMaterial({ color: 0x45a29e, side: THREE.DoubleSide, transparent: true, opacity: 0.5 })
                );
                planRing.rotation.x = -Math.PI / 2;
                planRing.position.y = 0.1;
                planHelper.add(planRing);
                planHelper.userData = { name: 'plan' };
                this.helpers.add(planHelper);

                // 3. Elevation Helper: Front Face
                const elevHelper = new THREE.Group();
                // Create a plane representing the front face
                const elevShape = new THREE.Shape();
                elevShape.moveTo(-CONFIG.baseRadius, 0);
                elevShape.lineTo(-CONFIG.baseRadius, CONFIG.height);
                elevShape.lineTo(CONFIG.baseRadius, CONFIG.height);
                elevShape.lineTo(CONFIG.baseRadius, 0);
                elevShape.lineTo(-CONFIG.baseRadius, 0);

                const elevGeo = new THREE.ShapeGeometry(elevShape);
                const elevMat = new THREE.MeshBasicMaterial({ color: 0x45a29e, side: THREE.DoubleSide, transparent: true, opacity: 0.2, wireframe: true });
                const elevMesh = new THREE.Mesh(elevGeo, elevMat);
                elevHelper.add(elevMesh);
                elevHelper.userData = { name: 'elevation' };
                this.helpers.add(elevHelper);

                // 4. Section Helper: Cross Section
                const secHelper = new THREE.Group();
                const secShape = new THREE.Shape();
                secShape.moveTo(-CONFIG.baseRadius, 0);
                secShape.lineTo(CONFIG.baseRadius, 0);
                secShape.lineTo(CONFIG.topRadius, CONFIG.height);
                secShape.lineTo(-CONFIG.topRadius, CONFIG.height);
                secShape.lineTo(-CONFIG.baseRadius, 0);

                const secGeo = new THREE.ShapeGeometry(secShape);
                const secMat = new THREE.MeshBasicMaterial({ color: 0x45a29e, side: THREE.DoubleSide, transparent: true, opacity: 0.2, wireframe: true });
                const secMesh = new THREE.Mesh(secGeo, secMat);
                secHelper.add(secMesh);
                secHelper.userData = { name: 'section' };
                this.helpers.add(secHelper);
            }

            setStage(stageName) {
                this.currentStage = stageName;

                // Update UI
                const data = STAGE_DATA[stageName];
                document.getElementById('stage-info').innerHTML = `<p>${data.desc}</p>`;
                document.getElementById('drawing-info').innerHTML = `<p>${data.drawing}</p><div class="dimension-box">단위: 미터 (m)</div>`;

                // Update Tabs
                document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
                event.target.classList.add('active');

                // Update Camera
                this.controls.target.set(data.target.x, data.target.y, data.target.z);
                this.camera.position.set(data.cameraPos.x, data.cameraPos.y, data.cameraPos.z);
                this.controls.update();

                // Update Helpers
                this.helpers.children.forEach(helper => {
                    if (helper.userData.name === stageName) {
                        helper.visible = true;
                        helper.scale.set(1, 1, 1);
                    } else {
                        helper.visible = false;
                    }
                });
            }

            resetCamera() {
                const data = STAGE_DATA[this.currentStage];
                this.controls.target.set(data.target.x, data.target.y, data.target.z);
                this.camera.position.set(data.cameraPos.x, data.cameraPos.y, data.cameraPos.z);
                this.controls.update();
            }

            toggleAutoRotate() {
                this.isAutoRotating = !this.isAutoRotating;
                this.controls.autoRotate = this.isAutoRotating;
                document.getElementById('rotate-status').innerText = this.isAutoRotating ? "ON" : "OFF";
            }

            toggleWireframe() {
                this.isWireframe = !this.isWireframe;
                this.wireframeGroup.visible = this.isWireframe;
            }

            setupEvents() {
                window.addEventListener('resize', () => {
                    this.camera.aspect = window.innerWidth / window.innerHeight;
                    this.camera.updateProjectionMatrix();
                    this.renderer.setSize(window.innerWidth, window.innerHeight);
                });
            }

            animate() {
                requestAnimationFrame(() => this.animate());
                this.controls.update();
                this.renderer.render(this.scene, this.camera);
            }
        }

        // Initialize App
        const app = new App();
        // Expose to window for HTML buttons
        window.app = app;
    </script>
